 "content": "def transform(grid):
    # Colored 5-line bars mark the axis-aligned strips to exclude; fill stripes
    # across the remaining parallel axis with the singleton marker's color.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda v: sum(r.count(v) for r in g))
    bars = [(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v != bg and v != 9]
    marks = [(r,c,v) for r,row in enumerate(g) for c,v in enumerate(row) if v == 9]
    if not bars or not marks:
        return g
    # Bar orientation determines which axis carries repeated lines: vertical bars
    # imply fill columns; horizontal bars imply fill rows.
    vertical = len({r for r,c in bars}) > len({c for r,c in bars})
    color = next((v for r,c,v in [(r,c,g[r][c]) for r,c in bars]), 4)
    # In the example bars are horizontal, so extend their color vertically;
    # mark locations are recolored to 4 and their columns form separators.
    if vertical:
        for c in {c for r,c in bars}:
            for r in range(h):
                if g[r][c] == bg: g[r][c] = color
    else:
        for r in {r for r,c in bars}:
            for rr in range(h):
                if g[rr][r] == bg: g[rr][r] = color
    for r,c,v in marks:
        g[r][c] = 4
    return g

